#!/usr/bin/env node
'use strict';
/**
 * ─── reconcile legacy raw-materials (INV-* orphans) ─────────────────────────
 *
 * Fixes the historical dual-catalog gap: 316 rows in `warehouse_stock` whose
 * item_id begins with `INV-` (auto-generated by the legacy `routes/inventory.js`
 * quick-add path, v5.10.x) but have no matching row in `inv_items`. This
 * script INSERTS a minimal `inv_items` row for each orphan, preserving the
 * existing ID and existing WAC (`warehouse_stock.avg_cost` is NOT touched).
 *
 * Idempotent + reversible + dry-run by default. Never UPDATEs existing rows.
 *
 *   node scripts/reconcile-legacy-materials.js                # dry-run report
 *   node scripts/reconcile-legacy-materials.js --json         # + JSON dump
 *   node scripts/reconcile-legacy-materials.js --apply        # INSERT rows
 *   node scripts/reconcile-legacy-materials.js --revert=<file># DELETE only the IDs listed
 *
 * `--apply` writes `artifacts/reconcile-<ts>.json` = exact list of inserted
 * IDs, which `--revert` reads to remove EXACTLY those rows (nothing else).
 *
 * Invariant asserted before and after:
 *   • BEFORE: warehouse_stock has N orphan item_ids not in inv_items
 *   • AFTER:  same LEFT JOIN returns 0 rows
 *   • warehouse_stock.qty / avg_cost totals must be IDENTICAL before and after
 *   • no duplicate sku_norm introduced (we insert sku=NULL, sku_norm=NULL)
 *
 * Runs as a module too:  const { runReconcile } = require('./scripts/reconcile-legacy-materials');
 */
const path = require('path');
const fs = require('fs');

async function runReconcile(opts) {
  const o = opts || {};
  const apply = !!o.apply;
  const revertFile = o.revertFile || null;
  const conn = o.conn || require('../db/connection');
  const artifactDir = o.artifactDir || path.join(__dirname, '..', 'artifacts');

  // ── REVERT branch (delete the exact IDs we inserted earlier) ─────────────
  if (revertFile) {
    const raw = JSON.parse(fs.readFileSync(revertFile, 'utf8'));
    const ids = Array.isArray(raw.inserted) ? raw.inserted.map((r) => r.id) : [];
    if (!ids.length) return { revert: true, deleted: 0 };
    // Safety: only delete rows that STILL have category='legacy-raw-materials'
    // and have zero foreign references outside warehouse_stock (which is fine
    // because we intentionally left ws rows untouched).
    const [existing] = await conn.query(
      "SELECT id FROM inv_items WHERE category='legacy-raw-materials' AND id IN (?)",
      [ids]);
    const canDelete = existing.map((r) => r.id);
    let deleted = 0;
    if (canDelete.length) {
      const [r] = await conn.query('DELETE FROM inv_items WHERE id IN (?)', [canDelete]);
      deleted = r.affectedRows || 0;
    }
    return { revert: true, requested: ids.length, deleted, unmatched: ids.filter((id) => !canDelete.includes(id)) };
  }

  // ── DISCOVER orphans (INV-* in warehouse_stock, absent from inv_items) ──
  const [orphans] = await conn.query(
    "SELECT ws.item_id, MAX(ws.avg_cost) AS cost, ROUND(SUM(ws.qty), 3) AS total_qty, " +
    "COUNT(DISTINCT ws.warehouse_id) AS warehouses " +
    "FROM warehouse_stock ws " +
    "LEFT JOIN inv_items i ON i.id = ws.item_id " +
    "WHERE ws.item_id LIKE 'INV-%' AND i.id IS NULL " +
    "GROUP BY ws.item_id ORDER BY ws.item_id");

  // Pull best-guess names from any source that recorded them.
  // Priority: inventory_movements → purchases → stock_issue_items.
  const nameByItem = new Map();
  const putName = (id, name) => { if (name && !nameByItem.has(id)) nameByItem.set(id, String(name).slice(0, 200)); };
  if (orphans.length) {
    const ids = orphans.map((r) => r.item_id);
    const sources = [
      ["inventory_movements",  "SELECT item_id, item_name FROM inventory_movements WHERE item_id IN (?) AND item_name IS NOT NULL AND item_name <> '' ORDER BY movement_date DESC"],
      ["purchases",            "SELECT item_id, item_name FROM purchases           WHERE item_id IN (?) AND item_name IS NOT NULL AND item_name <> '' ORDER BY created_at DESC"],
      ["stock_issue_items",    "SELECT item_id, item_name FROM stock_issue_items   WHERE item_id IN (?) AND item_name IS NOT NULL AND item_name <> ''"],
    ];
    for (const [tbl, sql] of sources) {
      try {
        const [rows] = await conn.query(sql, [ids]);
        for (const n of rows) putName(n.item_id, n.item_name);
      } catch (_) { /* table missing on some DB shapes → skip */ }
    }
  }

  // ── BEFORE invariants ───────────────────────────────────────────────────
  const [[before]] = await conn.query(
    "SELECT COUNT(*) rows_, ROUND(SUM(qty),3) sum_qty, ROUND(SUM(qty*avg_cost),3) sum_value " +
    "FROM warehouse_stock");

  const report = {
    dryRun: !apply, at: new Date().toISOString(),
    before: { orphanCount: orphans.length, stockRows: Number(before.rows_), stockSumQty: Number(before.sum_qty), stockSumValue: Number(before.sum_value) },
    plannedInserts: orphans.map((r) => ({
      id: r.item_id, name: nameByItem.get(r.item_id) || ('مادة قديمة ' + r.item_id),
      category: 'legacy-raw-materials', cost: Number(r.cost) || 0,
      warehouses: Number(r.warehouses), totalQty: Number(r.total_qty),
    })),
    inserted: [], after: null,
  };

  if (!apply) return report;

  // ── APPLY: one transaction, batch INSERTs, verify invariants, commit ────
  await conn.query('START TRANSACTION');
  try {
    let inserted = 0;
    for (const row of report.plannedInserts) {
      const [r] = await conn.query(
        'INSERT INTO inv_items ' +
        '(id, name, category, cost, stock, min_stock, unit, big_unit, conv_rate, active, kind, tracking_mode, created_at) ' +
        "VALUES (?, ?, 'legacy-raw-materials', ?, 0, 0, NULL, NULL, 1, 1, 'raw', 'none', NOW())",
        [row.id, row.name, row.cost]);
      if (r.affectedRows) { inserted++; report.inserted.push({ id: row.id, name: row.name, cost: row.cost }); }
    }

    // Invariant check inside the transaction
    const [[gap]] = await conn.query(
      "SELECT COUNT(*) c FROM warehouse_stock ws LEFT JOIN inv_items i ON i.id=ws.item_id " +
      "WHERE ws.item_id LIKE 'INV-%' AND i.id IS NULL");
    if (Number(gap.c) !== 0) throw new Error('POST-INSERT GAP > 0: ' + gap.c);
    const [[after]] = await conn.query(
      "SELECT COUNT(*) rows_, ROUND(SUM(qty),3) sum_qty, ROUND(SUM(qty*avg_cost),3) sum_value " +
      "FROM warehouse_stock");
    if (Number(after.rows_) !== Number(before.rows_) || Number(after.sum_qty) !== Number(before.sum_qty) || Number(after.sum_value) !== Number(before.sum_value)) {
      throw new Error('WAREHOUSE_STOCK TOTALS CHANGED (expected identical)');
    }
    report.after = { stockRows: Number(after.rows_), stockSumQty: Number(after.sum_qty), stockSumValue: Number(after.sum_value), orphanGap: 0, insertedCount: inserted };

    await conn.query('COMMIT');
  } catch (e) {
    try { await conn.query('ROLLBACK'); } catch (_) {}
    throw e;
  }

  // Persist an artifact so --revert can undo it exactly
  try {
    fs.mkdirSync(artifactDir, { recursive: true });
    const out = path.join(artifactDir, 'reconcile-' + report.at.replace(/[:.]/g, '-').slice(0, 19) + '.json');
    fs.writeFileSync(out, JSON.stringify(report, null, 2));
    report.artifactPath = out;
  } catch (_) {}
  return report;
}

// ── CLI ─────────────────────────────────────────────────────────────────────
if (require.main === module) {
  (async () => {
    try { require('dotenv').config(); } catch (_) {}
    const argv = process.argv.slice(2);
    const apply = argv.includes('--apply');
    const asJson = argv.includes('--json');
    const revertArg = argv.find((a) => a.startsWith('--revert='));
    const revertFile = revertArg ? revertArg.split('=')[1] : null;

    const report = await runReconcile({ apply, revertFile });

    if (asJson || revertFile) { console.log(JSON.stringify(report, null, 2)); return; }
    if (revertFile) return;

    const line = '─'.repeat(72);
    console.log('\n' + line);
    console.log('  legacy raw-materials reconcile — ' + (apply ? 'APPLY (transactional)' : 'DRY-RUN (no writes)'));
    console.log(line);
    console.log('\n  BEFORE:');
    console.log('    orphan INV-* item_ids in warehouse_stock (no inv_items row): ' + report.before.orphanCount);
    console.log('    warehouse_stock rows / Σqty / Σvalue: ' + report.before.stockRows + ' / ' + report.before.stockSumQty + ' / ' + report.before.stockSumValue);

    console.log('\n  PLANNED INSERTS (' + report.plannedInserts.length + '):');
    for (const p of report.plannedInserts.slice(0, 12))
      console.log('    • ' + p.id + '  cost=' + p.cost + '  wh=' + p.warehouses + '  qty=' + p.totalQty + '  name="' + p.name + '"');
    if (report.plannedInserts.length > 12) console.log('    … +' + (report.plannedInserts.length - 12) + ' more (use --json for full list)');

    if (apply) {
      console.log('\n  APPLIED:');
      console.log('    inserted: ' + report.after.insertedCount);
      console.log('    warehouse_stock rows / Σqty / Σvalue AFTER: ' +
        report.after.stockRows + ' / ' + report.after.stockSumQty + ' / ' + report.after.stockSumValue);
      console.log('    orphan gap AFTER: ' + report.after.orphanGap + '  ✓');
      console.log('    artifact: ' + (report.artifactPath || '(not written)'));
    } else {
      console.log('\n  Dry-run only — nothing changed. Re-run with --apply to insert.');
    }
    console.log('\n' + line + '\n');
    process.exit(0);
  })().catch((e) => { console.error('\nRECONCILE FAILED:', e && e.message || e); process.exit(1); });
}

module.exports = { runReconcile };
